questions.question:
以下代码的输出是？
```c
int x = 10;
int *p = &x;
*p = 20;
printf("%d", x);
```

questions.code:
#include <stdio.h>
int main() {
    int x = 10;
    int *p = &x;    // p 指向 x

    printf("x = %d\n", x);      // 10
    printf("*p = %d\n", *p);    // 10

    *p = 20;  // 通过指针修改 x
    printf("x = %d\n", x);      // 20

    return 0;
}

